//! Bridges exchange-client Redis publications into live market state.
use futures_util::StreamExt;use std::time::{SystemTime,UNIX_EPOCH};use teloxide::prelude::*;use teloxide::types::ChatId;use crate::handlers::AppState;use crate::i18n;
const SMART_ALERT_COOLDOWN_MS:i64=15*60*1000;
fn now_millis()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis() as i64}
pub async fn run(redis_url:String,bot:Bot,state:AppState)->redis::RedisResult<()>{let client=redis::Client::open(redis_url)?;let mut pubsub=client.get_async_pubsub().await?;pubsub.psubscribe("candles:*").await?;pubsub.psubscribe("orderbook:*").await?;pubsub.psubscribe("funding:*").await?;pubsub.psubscribe("open_interest:*").await?;let mut messages=pubsub.on_message();while let Some(message)=messages.next().await{let channel=message.get_channel_name().to_string();let Ok(payload)=message.get_payload::<String>()else{continue};let score=if channel.starts_with("candles:"){serde_json::from_str::<shared::Candle>(&payload).ok().and_then(|x|state.market_state.ingest_candle(x))}else if channel.starts_with("orderbook:"){serde_json::from_str::<shared::OrderBookSnapshot>(&payload).ok().and_then(|x|state.market_state.ingest_order_book(x))}else if channel.starts_with("funding:"){serde_json::from_str::<shared::FundingRate>(&payload).ok().and_then(|x|state.market_state.ingest_funding_rate(x))}else if channel.starts_with("open_interest:"){serde_json::from_str::<shared::OpenInterest>(&payload).ok().and_then(|x|state.market_state.ingest_open_interest(x))}else{None};let Some(score)=score else{continue};for(telegram_id,threshold)in state.alarms.crossed(&score.symbol,score.value){notify_alarm(&bot,&state,telegram_id,&score,threshold).await;}if let Some(derivatives)=state.market_state.latest_derivatives(&score.symbol){let risk=derivatives.leverage_score;let agreement=(100.0-(score.value-derivatives.derivatives_score).abs()).clamp(0.0,100.0);let data_quality=if derivatives.oi_change_pct.is_finite()&&derivatives.funding_rate.is_finite(){85.0}else{40.0};let decision=score_engine::meta_decision(score.value,agreement,data_quality,risk);if let Some(alert)=state.smart_alerts.evaluate(&score.symbol,&decision,now_millis(),SMART_ALERT_COOLDOWN_MS){tracing::info!(symbol=%alert.symbol,decision=?alert.decision,confidence=alert.confidence,risk=alert.risk,"smart market alert");}}}Ok(())}
async fn notify_alarm(bot:&Bot,state:&AppState,telegram_id:i64,score:&shared::Score,threshold:f64){let lang=match state.user_store.get(telegram_id).await{Some(user)=>user.language,None=>"en".into()};let body=i18n::t_args(&lang,"alarm-triggered",&[("symbol",score.symbol.clone()),("threshold",format!("{:.1}",threshold)),("score",format!("{:.1}",score.value))]);let text=i18n::with_footer(&lang,&body);if let Err(err)=bot.send_message(ChatId(telegram_id),text).await{tracing::warn!(error=%err,"failed to send alarm notification");}}
